INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(24096228, 'Double Spell', '二重魔法', '二重魔法', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡丢弃1张魔法卡，选择对方墓地1张魔法卡才能发动。选择的魔法卡在自己场上的正确卡区域放置并使用。'),
(43422537, 'Double Summon', '二重召唤', '二重召喚', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合自己可以进行通常召唤最多2次。'),
(67223587, 'Double Tag Team', '障碍赛！', 'ハンディキャップマッチ！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己把名字带有「剑斗兽」的怪兽的特殊召唤成功时才能发动。从自己的手卡·卡组把1只名字带有「剑斗兽」的4星以下的怪兽特殊召唤。'),
(63730624, 'Double Tool C&D', '两件套工具D&C', 'ダブルツールD＆C', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的「动力工具龙」或者4星以上的机械族「变形斗士」怪兽才能装备。 ①：每回合让以下效果适用。 ●自己回合：装备怪兽的攻击力上升1000，成为装备怪兽的攻击对象的怪兽的效果只在那次战斗阶段内无效化。 ●对方回合：对方不能选择装备怪兽以外的怪兽作为攻击对象。 ②：对方回合，装备怪兽和对方怪兽进行战斗的伤害步骤结束时发动。那只对方怪兽破坏。'),
(51976476, 'Double Trap Hole', '卑鄙的落穴', '姑息な落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方把怪兽守备表示特殊召唤时才能发动。那些守备表示怪兽除外。'),
(67724434, 'Double Wild', '双重百搭', 'ダブル・ワイルド', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只5星以下的怪兽为对象才能发动。原本种族和那只怪兽相同的1只10星怪兽从卡组加入手卡。那之后，以下效果可以适用。这张卡的发动后，直到回合结束时自己不是原本种族和作为对象的怪兽相同的怪兽不能特殊召唤。 ●选自己1张手卡丢弃，种族和这个效果加入的怪兽相同的怪兽从手卡守备表示特殊召唤。'),
(41927278, 'Double-Edged Sword', '脆刃之剑', '脆刃の剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：「脆刃之剑」在自己场上只能有1张表侧表示存在。 ②：装备怪兽的攻击力上升2000，装备怪兽的战斗发生的战斗伤害由双方玩家承受。 ③：自己受到2000以上的战斗伤害的场合发动。这张卡送去墓地。'),
(21007444, 'Double-Edged Sword Technique', '诸刃的活人剑术', '諸刃の活人剣術', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地2只「六武众」怪兽为对象才能发动。那些怪兽攻击表示特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段破坏，自己受到破坏的怪兽的攻击力合计数值的伤害。'),
(55349196, 'Double-Headed Dino King Rex', '双头龙 恐龙王', '双頭竜キング・レックス', 'Effect Monster', 'Dinosaur', 'EARTH', 6, 1600, 1200, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，以持有比自己场上的恐龙族怪兽的攻击力合计低的攻击力的场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(23971061, 'Doublebyte Dragon', '双字节龙', 'ダブルバイト・ドラゴン', 'Link Monster', 'Cyberse', 'DARK', NULL, 1500, NULL, '连接怪兽2只 ①：这张卡的攻击力上升作为这张卡的连接素材的怪兽的连接标记合计×300。 ②：这张卡只要在怪兽区域存在，不受连接怪兽以外的怪兽的效果影响，不会被和连接怪兽以外的怪兽的战斗破坏。'),
(76382116, 'Dovelgus, Generaider Boss of Iron', '铁之创王 铁威古斯', '鉄の王 ドヴェルグス', 'Effect Monster', 'Machine', 'EARTH', 9, 1500, 2500, '这个卡名的②的效果1回合只能使用1次。 ①：「铁界王战 矮人联合王」在自己场上只能有1只表侧表示存在。 ②：把自己场上的「王战」怪兽或者机械族怪兽任意数量解放才能发动。把解放数量的和解放的怪兽卡名不同的，「王战」怪兽或者机械族怪兽从手卡守备表示特殊召唤（同名卡最多1张）。这个效果在对方回合也能发动。'),
(96540, 'Downbeat', '降拍', 'ダウンビート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只表侧表示怪兽解放才能发动。和解放的怪兽是原本的种族·属性相同而原本等级低1星的1只怪兽从卡组特殊召唤。'),
(72167543, 'Downerd Magician', '阴沉书呆魔术师', 'ダウナード・マジシャン', 'XYZ Monster', 'Spellcaster', 'DARK', 4, 2100, 200, '魔法师族4星怪兽×2 这张卡也能在自己主要阶段2在自己场上的3阶以下的超量怪兽上面重叠来超量召唤。 ①：这张卡的攻击力上升这张卡的超量素材数量×200。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：这张卡进行战斗的伤害计算后发动。这张卡1个超量素材取除。'),
(72490637, 'Dowsing Fusion', '探测结合', 'ダウジング・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地把融合怪兽卡决定的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。这个效果融合召唤的场合，不是灵摆怪兽不能作为融合素材。'),
(88413677, 'Doyon @Ignister', '郁闷闷＠伊格尼斯者', 'ドヨン＠イグニスター', 'Effect Monster', 'Cyberse', 'DARK', 4, 400, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以自己墓地1只「@火灵天星」怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡作为电子界族连接怪兽的连接素材送去墓地的场合，以自己墓地1张「“艾”」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(40702028, 'DPH Gendamoore', 'DPA 摩尔枪骑兵', 'DPAジャンダムーア', 'Synchro Tuner Monster', 'Cyberse', 'FIRE', 8, 2000, 2800, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从自己墓地把1只电子界族·4星怪兽效果无效守备表示特殊召唤。这个回合，自己不是电子界族怪兽不能特殊召唤。 ②：自己的电子界族怪兽用和对方怪兽的战斗给与对方战斗伤害时，把墓地的这张卡除外才能发动。给与对方那个数值的伤害。'),
(27995943, 'Dr. Frankenderp', '科学快人博士', 'Dr.フランゲ', 'Effect Monster', 'Psychic', 'DARK', 3, 300, 300, '「科学快人博士」的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，支付500基本分才能发动。自己把卡组最上面的卡确认。那之后，确认的卡回到卡组最下面或给对方观看并加入手卡。加入手卡的场合，下次的自己抽卡阶段跳过。'),
(66092596, 'Draco Awakening', '龙呼双搏', '竜呼双搏', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把以下怪兽之内1只加入手卡。 ●「真龙」怪兽 ●「龙剑士」灵摆怪兽 ●「龙魔王」灵摆怪兽 ②：自己场上的表侧表示的「真龙」怪兽被战斗·效果破坏送去墓地的场合，以那之内的1只为对象才能发动。那只怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(5041348, 'Draco Berserker of the Tenyi', '天威之龙鬼神', '天威の龍鬼神', 'Synchro Monster', 'Wyrm', 'DARK', 8, 3000, NULL, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：对方把怪兽的效果发动时才能发动。那只怪兽除外。 ②：这张卡的攻击破坏效果怪兽送去墓地的场合发动。这张卡的攻击力上升破坏的怪兽的原本攻击力数值。这次战斗阶段中，这张卡只再1次可以向怪兽攻击。'),
(14733538, 'Draco Face-Off', '龙呼相争', '竜呼相打つ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「龙呼相争」在1回合只能发动1张。 ①：从卡组选1只「龙剑士」灵摆怪兽和1只「龙魔王」灵摆怪兽给对方观看，对方从那之中随机选1只。对方选的灵摆怪兽在自己的灵摆区域放置或特殊召唤。剩下的灵摆怪兽表侧表示加入自己的额外卡组。'),
(23935886, 'Draco Masters of the Tenyi', '天威之龙拳圣', '天威の龍拳聖', 'Link Monster', 'Wyrm', 'LIGHT', NULL, 2600, NULL, '包含连接怪兽的怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡不会被和效果怪兽的战斗破坏。 ②：自己场上没有其他的效果怪兽存在的场合才能发动。选最多有自己墓地以及自己场上表侧表示存在的除效果怪兽以外的怪兽数量的对方场上的效果怪兽破坏。'),
(9070454, 'Draco-Utopian Aura', '龙皇之波动', '龍皇の波動', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方把场上的怪兽的效果发动时才能发动。那个发动无效并破坏。那之后，以下效果可以适用。 ●从自己手卡选1只怪兽除外，这个效果破坏送去墓地的怪兽效果无效在自己场上特殊召唤。'),
(38745520, 'Dracoback, the Rideable Dragon', '骑龙 多拉贡巴克', '騎竜ドラコバック', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的怪兽才能装备。这个卡名的②③的效果1回合各能使用1次。 ①：「骑龙 驮龙」在自己场上只能有1张表侧表示存在。 ②：这张卡给效果怪兽以外的怪兽装备中的场合，以对方场上1张卡为对象才能发动。那张卡回到持有者手卡。 ③：这张卡被送去墓地的场合，以自己场上1只「勇者衍生物」为对象才能发动。那只自己怪兽把这张卡装备。'),
(16960351, 'Dracocension', '幻界突破', '幻界突破', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，把自己场上1只龙族怪兽解放才能发动。和解放的怪兽的原本等级相同等级的1只幻龙族怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽战斗破坏的怪兽不送去墓地回到持有者卡组。'),
(90887783, 'Draconnection', '龙之交感', '竜の交感', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把手卡1只龙族怪兽给对方观看，和给人观看的怪兽相同等级的1只龙族怪兽从卡组加入手卡。那之后，给人观看的怪兽回到卡组。'),
(62706865, 'Draconnet', '网联幼龙', 'ドラコネット', 'Effect Monster', 'Cyberse', 'DARK', 3, 1400, 1200, '①：这张卡召唤成功时才能发动。从手卡·卡组把1只2星以下的通常怪兽守备表示特殊召唤。'),
(42596828, 'Dracoon Lamp', '龙狸灯', '龍狸燈', 'Effect Monster', 'Wyrm', 'FIRE', 4, 500, 2000, '①：1回合1次，从手卡丢弃1只幻龙族怪兽才能发动。这张卡的守备力直到回合结束时上升1000。这个效果在对方回合也能发动。 ②：攻击表示的这张卡和攻击表示怪兽进行战斗的伤害计算时才能发动1次。那次战斗用双方怪兽的守备力当作攻击力使用进行伤害计算。'),
(33760966, 'Dracotail Arthalion', '星宿爪龙 阿尔扎里昂', '星辰爪竜アルザリオン', 'Fusion Monster', 'Dragon', 'EARTH', 8, 3000, 2500, '「星辰」怪兽＋手卡的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤的场合，以最多有那些作为融合素材的手卡的怪兽数量的自己·对方的场上·墓地的怪兽为对象才能发动。那些怪兽回到手卡。 ②：这张卡在墓地存在的状态，怪兽2只以上同时被送去墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(1498449, 'Dracotail Faimena', '星宿炮手 法魅那', '星辰砲手ファイメナ', 'Effect Monster', 'Spellcaster', 'WATER', 5, 1300, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把这张卡从手卡丢弃才能发动。自己的手卡·场上的怪兽作为融合素材，把1只龙族·魔法师族的融合怪兽融合召唤。 ②：这张卡成为融合召唤的素材送去墓地的场合才能发动。从卡组把1张「星辰」魔法·陷阱卡在自己场上盖放。'),
(5431722, 'Dracotail Flame', '星宿之吼炎', '星辰の吼炎', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以场上1张表侧表示的魔法卡为对象才能发动。那张卡的效果直到回合结束时无效。那之后，以下效果可以适用。 ●「星辰的吼炎」以外的自己的墓地·除外状态的1张「星辰」卡回到卡组最下面。那之后，自己抽1张。'),
(79755671, 'Dracotail Gulamel', '星宿法宫 格拉梅尔', '星辰法宮グラメル', 'Fusion Monster', 'Spellcaster', 'WATER', 7, 2800, 2300, '「星辰」怪兽＋手卡的怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：自己把「星辰」卡的效果发动时，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：这张卡在墓地存在的状态，怪兽2只以上同时被送去墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(69932023, 'Dracotail Horn', '星宿之裂角', '星辰の裂角', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以场上1只攻击表示怪兽为对象才能发动。那只怪兽回到手卡·额外卡组。那之后，以下效果可以适用。 ●「星辰的裂角」以外的自己的墓地·除外状态的1张「星辰」卡回到卡组最下面。那之后，自己抽1张。'),
(75003700, 'Dracotail Lukias', '星宿枪手 卢奇亚斯', '星辰槍手ルキアス', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1800, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「星辰枪手 巨蟹魔」以外的1只「星辰」怪兽加入手卡。 ②：这张卡成为融合召唤的素材送去墓地的场合才能发动。从卡组把1张「星辰」魔法·陷阱卡在自己场上盖放。'),
(7375867, 'Dracotail Mululu', '星宿龙 姆露露', '星辰竜ムルル', 'Effect Monster', 'Dragon', 'DARK', 3, 1100, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「星辰」融合怪兽融合召唤。这个回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ②：这张卡成为融合召唤的素材送去墓地的场合才能发动。从卡组把1张「星辰」魔法·陷阱卡在自己场上盖放。那之后，可以把对方场上1只表侧表示怪兽的效果无效。'),
(44482554, 'Dracotail Pan', '星宿龙 潘', '星辰竜パーン', 'Effect Monster', 'Dragon', 'WIND', 7, 2700, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡成为融合召唤的素材送去墓地的场合才能发动。从卡组把1张「星辰」魔法·陷阱卡在自己场上盖放。那之后，可以把场上1只怪兽破坏。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的融合怪兽被对方的效果破坏的场合才能发动。这张卡回到卡组最下面，从自己墓地把融合怪兽以外的1只「星辰」怪兽特殊召唤。'),
(84477320, 'Dracotail Phryxul', '星宿响手 普莉库露', '星辰響手プリクル', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 800, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以「星辰响手 金牛魔」以外的自己墓地1只「星辰」怪兽为对象才能发动。那只怪兽特殊召唤。那之后，自己场上1只怪兽回到手卡。 ②：这张卡成为融合召唤的素材送去墓地的场合才能发动。从卡组把1张「星辰」魔法·陷阱卡在自己场上盖放。'),
(42125140, 'Dracotail Shaulas', '星宿钳龙 夏乌拉斯', '星辰鋏竜シャウラス', 'Fusion Monster', 'Dragon', 'LIGHT', 6, 2400, 1500, '「星辰」怪兽＋手卡的怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地2张「星辰」卡和与那其中任意张是相同种类（怪兽·魔法·陷阱）的场上1张表侧表示卡为对象才能发动。那3张卡回到卡组。 ②：这张卡在墓地存在的状态，怪兽2只以上同时被送去墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(80208225, 'Dracotail Sting', '星宿之刺毒', '星辰の刺毒', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方墓地的怪兽和魔法·陷阱卡各最多1张为对象才能发动。那些卡除外。那之后，以下效果可以适用。 ●「星辰的刺毒」以外的自己的墓地·除外状态的1张「星辰」卡回到卡组最下面。那之后，自己抽1张。'),
(70871153, 'Dracotail Urgula', '星宿龙 乌尔格拉', '星辰竜ウルグラ', 'Effect Monster', 'Dragon', 'FIRE', 6, 2400, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡成为融合召唤的素材送去墓地的场合才能发动。从卡组把1张「星辰」魔法·陷阱卡在自己场上盖放。那之后，可以把场上1张魔法·陷阱卡破坏。 ②：这张卡在墓地存在的场合，以自己墓地1只魔法师族「星辰」怪兽为对象才能发动。这张卡回到卡组最下面，作为对象的怪兽加入手卡。'),
(65737274, 'Dragard', '龙龙', 'ドラゴラド', 'Effect Monster', 'Dragon', 'DARK', 4, 1300, 1900, '①：这张卡召唤成功时，以自己墓地1只攻击力1000以下的通常怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：1回合1次，把自己场上1只龙族怪兽解放，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时等级变成8星，攻击力上升800。'),
(16435215, 'Dragged Down into the Grave', '墓穴的同路人', '墓穴の道連れ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方各自把对方手卡确认，从那之中选1张卡丢弃。那之后，双方各自从卡组抽1张。'),
(45593826, 'Draghig, Malebranche of the Burning Abyss', '彼岸恶鬼 德拉格涅', '彼岸の悪鬼 ドラゴネル', 'Effect Monster', 'Fiend', 'DARK', 3, 1100, 900, '「彼岸的恶鬼 德拉基尼亚佐」的①③的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。 ③：这张卡被送去墓地的场合才能发动。从卡组选1张「彼岸」卡在卡组最上面放置。'),
(21435914, 'Dragocytos Corrupted Nethersoul Dragon', '冥界浊龙 恸河龙', '冥界濁龍 ドラゴキュートス', 'Synchro Monster', 'Dragon', 'DARK', 10, 4000, 2000, '暗属性调整＋调整以外的龙族怪兽1只 ①：这张卡不会被战斗破坏。 ②：这张卡战斗破坏对方怪兽送去墓地时才能发动。这张卡只再1次可以继续向对方怪兽攻击。 ③：自己准备阶段以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成一半，给与对方那个数值的伤害。'),
(65472618, 'Dragodies, the Empowered Warrior', '魔装战士 龙天', '魔装戦士 ドラゴディウス', 'Pendulum Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 1500, '①：自己的怪兽区域的这张卡被对方怪兽的攻击或者对方的效果破坏的场合才能发动。这个回合的结束阶段，从卡组把「魔装战士 龙天」以外的攻击力2000以下的1只战士族或者魔法师族怪兽加入手卡。'),
(48705086, 'Dragolithia Kunzite', '玲珑龙 紫锂辉石龙', '玲瓏竜クンツァイド', 'Effect Monster', 'Dragon', 'EARTH', 8, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡在手卡存在的场合才能发动。从手卡·卡组把1只7星以上的通常怪兽送去墓地，这张卡特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1只通常怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(76218313, 'Dragon Buster Destruction Sword', '破坏剑-龙破坏之剑', '破壊剣－ドラゴンバスターブレード', 'Tuner Monster', 'Dragon', 'DARK', 1, 400, 300, '「破坏剑-龙破坏之剑」的③的效果1回合只能使用1次。 ①：自己主要阶段以自己场上1只「破坏之剑士」为对象才能发动。从自己的手卡·场上把这只怪兽当作装备卡使用给那只自己怪兽装备。 ②：这张卡装备中的场合，对方不能从额外卡组把怪兽特殊召唤。 ③：这张卡装备中的场合才能发动。装备的这张卡特殊召唤。'),
(300202003, 'Dragon Caller', NULL, NULL, 'Skill Card', 'Kaiba', NULL, NULL, NULL, NULL, NULL),
(50045299, 'Dragon Capture Jar', '龙族封印之壶', 'ドラゴン族・封印の壺', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，场上表侧表示存在的龙族怪兽全部变成守备表示，不能把表示形式变更。'),
(38955728, 'Dragon Core Hexer', '龙核的咒灵者', '竜核の呪霊者', 'Normal Tuner Monster', 'Dragon', 'DARK', 8, 2300, 3000, '长期以来持续猎龙而被龙血泼溅的缘故，得到了不属常人力量的女战士。其灵魂因沾染到所杀之龙的怨气，最终化为散布瘟疫的邪恶龙核。如今的她已经是无故乡可归，完全遵循着本能把刀剑染成血红，她自己也想不起那么做的目的了…。'),
(76066541, 'Dragon Dowser', '小龙探物摆', 'ドラゴンダウザー', 'Effect Monster', 'Wyrm', 'EARTH', 4, 1500, 1500, '「小龙探物摆」的效果1回合只能使用1次。 ①：场上的这张卡被战斗或者对方的效果破坏送去墓地时才能发动。从卡组把1只地属性灵摆怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(300302064, 'Dragon Force', NULL, NULL, 'Skill Card', 'Nightshroud', NULL, NULL, NULL, NULL, NULL),
(9567495, 'Dragon Gate', '斗龙门', '闘龍門', 'XYZ Monster', 'Zombie', 'EARTH', 6, 1100, 2800, '6星怪兽×2 「斗龙门」1回合1次也能在自己场上的3阶以下的超量怪兽上面重叠来超量召唤。这张卡在超量召唤的回合不能作为超量召唤的素材。 ①：1回合1次，可以发动。这张卡的超量素材任意数量取除。这张卡的攻击力上升取除的超量素材种类（怪兽·魔法·陷阱）×1000，对方场上有怪兽存在的场合，那些攻击力下降所上升的数值。这个回合，这张卡可以向对方怪兽全部各作1次攻击。'),
(21970285, 'Dragon Horn Hunter', '龙角的狩猎者', '竜角の狩猟者', 'Pendulum Normal Monster', 'Warrior', 'DARK', 6, 2300, 1000, '为了拯救瘟疫中受苦的故乡村庄，因灵药原料是龙之角而滥捕的女战士。那个村庄已经遭到被赶离巢穴的龙们践踏并烧毁一事，她还并不知情…'),
(64262809, 'Dragon Ice', '龙冰', 'ドラゴン・アイス', 'Effect Monster', 'Dragon', 'WATER', 5, 1800, 2200, '对方对怪兽的特殊召唤成功时，可以把自己1张手卡丢弃，这张卡从手卡或者墓地特殊召唤。「龙冰」在场上只能有1张表侧表示存在。'),
(14017402, 'Dragon Knight Draco-Equiste', '波动龙骑士', '波動竜騎士 ドラゴエクィテス', 'Fusion Monster', 'Dragon', 'WIND', 10, 3200, 2000, '龙族同调怪兽＋战士族怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。1回合1次，可以把墓地存在的1只龙族的同调怪兽从游戏中除外，直到结束阶段时当作和那只怪兽同名卡使用，得到相同效果。此外，只要这张卡在场上表侧攻击表示存在，对方的卡的效果发生的对自己的效果伤害由对方代受。'),
(87835759, 'Dragon Knight of Creation', '创世之龙骑士', '創世の竜騎士', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1800, 600, '这个卡名的③的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，这张卡的等级在对方回合内上升4星。 ②：这张卡战斗破坏对方怪兽送去墓地时才能发动。从卡组把1只7·8星的龙族怪兽送去墓地。 ③：把1张手卡送去墓地，以自己墓地1只7·8星的龙族怪兽为对象才能发动。这张卡送去墓地，作为对象的怪兽特殊召唤。'),
(29228350, 'Dragon Laser', '火龙镭射', 'ドラゴンレーザー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的「三角三」装备的1只「三角火龙」送去墓地，对方场上存在的怪兽全部破坏。'),
(69868556, 'Dragon Lord Token', '巨神龙的遗迹', '巨神竜の遺跡', 'Token', 'Dragon', NULL, NULL, NULL, NULL, NULL),
(63018132, 'Dragon Manipulator', '龙骑手', 'ドラゴン・ライダー', 'Flip Effect Monster', 'Warrior', 'EARTH', 3, 700, 800, '反转：在回合结束前得到对方场上的1只表侧表示存在的龙族怪兽。'),
(62873545, 'Dragon Master Knight', '究极龙骑士', '究極竜騎士', 'Fusion Monster', 'Dragon', 'LIGHT', 12, 5000, 5000, '「混沌战士」＋「青眼究极龙」 这张卡不用融合召唤不能特殊召唤。 ①：这张卡的攻击力上升自己场上的其他的龙族怪兽数量×500。'),
(58931850, 'Dragon Master Lords', '超究极魔导龙王', '超究極魔導竜王', 'XYZ Monster', 'Dragon', 'DARK', 12, 5000, 5000, '12星怪兽×2 ①：只要超量召唤的这张卡在怪兽区域存在，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。 ②：只要自己墓地有卡25张以上存在，这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的2倍数值的战斗伤害。 ③：1回合1次，对方墓地有卡25张以上存在的场合，把这张卡1个超量素材取除才能发动。从自己的卡组·额外卡组·墓地把1只怪兽特殊召唤。'),
(12381100, 'Dragon Master Magia', '究极龙魔导师', '究極竜魔導師', 'Fusion Monster', 'Dragon', 'LIGHT', 12, 5000, 4000, '「青眼究极龙」（或者「青眼」怪兽×3）＋「混沌」仪式怪兽 这张卡不用融合召唤不能特殊召唤。 ①：对方把效果发动时才能发动（这个卡名的这个效果在1回合对魔法·陷阱·怪兽的效果每种各能发动1次）。那个发动无效并破坏。 ②：表侧表示的这张卡因对方从场上离开的场合才能发动。从自己的额外卡组·墓地把1只「青眼」怪兽或「混沌」仪式怪兽特殊召唤。'),
(99659159, 'Dragon Mastery', '操龙术', '竜操術', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：有「龙骑兵团」怪兽卡装备的自己场上的怪兽的攻击力上升500。 ②：1回合1次，以自己场上1只表侧表示怪兽为对象才能发动。从手卡把1只龙族「龙骑兵团」怪兽当作装备卡使用给作为对象的自己怪兽装备。'),
(76076738, 'Dragon Nails', '暗龙族之爪', '闇竜族の爪', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '暗属性怪兽才能装备。这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽的攻击力上升600，不会被对方的效果破坏。 ②：装备怪兽被战斗破坏送去墓地让这张卡被送去墓地的场合才能发动。那只怪兽在自己场上特殊召唤，把这张卡装备。这个效果装备的这张卡从场上离开的场合除外。'),
(96823189, 'Dragon of Pride and Soul', '骄傲与灵魂之龙', '誇りと魂の龍', 'Effect Monster', 'Dragon', 'DARK', 8, 2500, 2500, '这张卡不能通常召唤。对方墓地有卡25张以上存在的场合才能特殊召唤。 ①：只要自己墓地有卡25张以上存在，这张卡的攻击力·守备力上升2500。'),
(55763552, 'Dragon Piper', '壶魔人', '壺魔人', 'Flip Effect Monster', 'Pyro', 'FIRE', 3, 200, 1800, '反转：场上表侧表示的「龙族封印之壶」破坏。破坏时，场上表侧表示存在的龙族怪兽全部攻击表示。'),
(80513550, 'Dragon Queen of Tragic Endings', '悲剧结局女王龙', 'バッド・エンド・クイーン・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 6, 1900, 2600, '这张卡不能通常召唤。自己场上有永续魔法卡3张以上表侧表示存在的场合可以特殊召唤。这张卡的攻击给与对方基本分战斗伤害时，对方选择1张手卡送去墓地，自己从卡组抽1张卡。此外，这张卡从场上送去墓地的场合，自己的准备阶段时，可以把自己场上表侧表示存在的1张永续魔法卡送去墓地，这张卡从墓地特殊召唤。'),
(62265044, 'Dragon Ravine', '龙之溪谷', '竜の渓谷', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，可以丢弃1张手卡，从以下效果选择1个发动。 ●从卡组把1只4星以下的「龙骑兵团」怪兽加入手卡。 ●从卡组把1只龙族怪兽送去墓地。'),
(71867500, 'Dragon Revival Rhapsody', '龙之复活狂想曲', 'ドラゴン・復活の狂奏', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有魔法师族怪兽存在的场合，以包含龙族通常怪兽的自己墓地最多2只龙族怪兽为对象才能发动。那些怪兽特殊召唤。这张卡的发动后，直到回合结束时对方受到的全部伤害变成0。'),
(28563545, 'Dragon Seeker', '杀龙者', '竜殺者', 'Effect Monster', 'Fiend', 'DARK', 6, 2000, 2100, '这张卡在场上召唤·反转召唤时，破坏表侧表示的1只龙族怪兽。'),
(63300440, 'Dragon Shield', '龙盾甲', 'ドラゴン・シールド', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '龙族怪兽才能装备。 ①：装备怪兽不会被战斗·效果破坏。装备怪兽的战斗发生的对双方玩家的战斗伤害变成0。'),
(41620959, 'Dragon Shrine', '龙之灵庙', '竜の霊廟', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只龙族怪兽送去墓地。这个效果送去墓地的怪兽是龙族通常怪兽的场合，可以再从卡组把1只龙族怪兽送去墓地。'),
(45467446, 'Dragon Spirit of White', '白之灵龙', '白き霊龍', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2500, 2000, '这个卡名在规则上也当作「青眼」卡使用。 ①：这张卡只要在手卡·墓地存在，当作通常怪兽使用。 ②：这张卡召唤·特殊召唤时，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡除外。 ③：自己·对方回合，对方场上有怪兽存在的场合，把这张卡解放才能发动。从手卡把1只「青眼白龙」特殊召唤。'),
(9197735, 'Dragon Statue', '龙魂之石像', '竜魂の石像', 'Normal Monster', 'Warrior', 'EARTH', 3, 1100, 900, '拥有龙的灵魂的石像战士。用自豪的剑劈开敌人。'),
(1435851, 'Dragon Treasure', '龙之秘宝', 'ドラゴンの秘宝', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '龙族才能装备。1只装备怪兽的攻击力·守备力上升300。'),
(66672569, 'Dragon Zombie', '龙丧尸', 'ドラゴン・ゾンビ', 'Normal Monster', 'Zombie', 'DARK', 3, 1600, NULL, '被魔力唤醒的龙，吐出的气息能使物体腐烂。'),
(16278116, 'Dragon''s Bind', '龙之束缚', '竜の束縛', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以自己场上1只攻击力·守备力是2500以下的龙族怪兽为对象才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，双方不能把作为对象的怪兽的原本攻击力以下的怪兽特殊召唤。 ②：作为对象的怪兽从场上离开时这张卡破坏。'),
(95697223, 'Dragon''s Fighting Spirit', '龙之斗志', '竜の闘志', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以这个回合特殊召唤的自己场上1只龙族怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中在通常攻击外加上可以作出最多有对方场上的这个回合特殊召唤的怪兽数量的攻击。'),
(55991637, 'Dragon''s Gunfire', '火龙的火炎弹', '火竜の火炎弾', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有龙族怪兽表侧表示存在的场合，从下面效果选择1个发动： ●给与对方基本分800分伤害。 ●选择场上表侧表示存在的1只守备力800以下的怪兽破坏。'),
(63295720, 'Dragon''s Light and Darkness', '龙之影光', '竜の影光', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●手卡1只龙族·8星怪兽回到卡组，和那只怪兽属性不同的1只龙族·8星怪兽从卡组加入手卡。 ●以自己场上1只龙族怪兽为对象才能发动。那只怪兽的攻击力上升自身的等级×200。 ●自己场上的龙族怪兽为对象的卡的效果发动时才能发动。那个效果无效。'),
(85442146, 'Dragon''s Mind', '龙之意志', '竜の精神', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有原本攻击力或者原本守备力是2500的怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ②：这张卡在墓地存在的场合，支付2500基本分才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(71490127, 'Dragon''s Mirror', '龙之镜', '龍の鏡', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的场上·墓地把龙族融合怪兽卡决定的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。'),
(54178050, 'Dragon''s Rage', '龙之逆鳞', '竜の逆鱗', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的龙族怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(20638610, 'Dragon''s Rebirth', '龙之转生', '竜の転生', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只龙族怪兽为对象才能发动。那只自己的龙族怪兽除外，从自己的手卡·墓地选1只龙族怪兽特殊召唤。'),
(84462118, 'Dragonbite', '龙咬虫', '竜咬蟲', 'Tuner Monster', 'Insect', 'DARK', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时才能发动。从手卡把1只4星以下的昆虫族怪兽特殊召唤。 ②：从自己的手卡·墓地以及自己场上的表侧表示怪兽之中把1只4星以下的昆虫族怪兽除外，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升除外的怪兽的等级数值。'),
(45667991, 'Dragoncaller Magician', '降龙之魔术师', '降竜の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 7, 2400, 1000, '①：1回合1次，自己主要阶段才能发动。这张卡的种族直到回合结束时变成龙族。 ②：场上的这张卡为素材作融合·同调·超量召唤的怪兽得到以下效果。 ●这张卡和龙族怪兽进行战斗的伤害步骤内，这张卡的攻击力变成原本攻击力的2倍。'),
(5325424, 'Dragoncarnation', '牙龙转生', '牙竜転生', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择从游戏中除外的1只自己的龙族怪兽加入手卡。'),
(8198620, 'Dragonecro Nethersoul Dragon', '冥界龙 亡灵龙', '冥界龍 ドラゴネクロ', 'Fusion Monster', 'Dragon', 'DARK', 8, 3000, NULL, '不死族怪兽×2 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：「冥界龙 龙亡」在自己场上只能有1只表侧表示存在。 ②：和这张卡进行战斗的怪兽不会被那次战斗破坏。 ③：这张卡和怪兽进行战斗的伤害步骤结束时发动。那只怪兽的攻击力变成0，把持有和那只怪兽的原本的等级·攻击力相同等级·攻击力的1只「暗魂体衍生物」（不死族·暗·攻?/守0）在自己场上特殊召唤。'),
(70681994, 'Dragoness the Wicked Knight', '魔装骑士 德拉格尼斯', '魔装騎士ドラゴネス', 'Fusion Monster', 'Warrior', 'WIND', 3, 1200, 900, '「铠甲剑尾战士」＋「独眼盾龙」'),
(83980492, 'Dragong', '铜锣龙', '銅鑼ドラゴン', 'Pendulum Normal Monster', 'Machine', 'EARTH', 4, 500, 2100, '驱使最新锐的技术，变得能飞行的战斗用铜锣。不得不对以0.7马赫飞翔于天空的其存在而感到惊愕。'),
(32437102, 'Dragonic Attack', '龙魂之力', '竜魂の力', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '只有战士族可以装备。装备怪兽的种族变龙族，攻击力守备力上升500。'),
(13035077, 'Dragonic Diagram', '龙叁阵 示图', 'ドラゴニックD', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「真龙」怪兽的攻击力·守备力上升300。 ②：只要这张卡在场地区域存在，上级召唤的「真龙」怪兽在1回合各有1次不会被战斗破坏。 ③：1回合1次，自己主要阶段才能发动。这张卡以外的自己的手卡·场上1张卡破坏，从卡组把1张「真龙」卡加入手卡。'),
(78009994, 'Dragonic Guard', '龙神守卫', 'ドラゴニック・ガード', 'Effect Monster', 'Dragon', 'FIRE', 4, 1500, 1800, '每次怪兽通常召唤，给这张卡放置1个龙神指示物。此外，可以把场上表侧表示存在的这张卡送去墓地，把持有这张卡放置的龙神指示物数量以下的等级的1只龙族怪兽从自己卡组特殊召唤。'),
(38109772, 'Dragonic Knight', '龙之骑士', '竜の騎士', 'Effect Monster', 'Dragon', 'FIRE', 7, 2800, 2300, '要让自己场上的卡破坏的效果由对方怪兽发动时，把成为对象的自己的卡全部送去墓地才能发动。这张卡从手卡特殊召唤。'),
(71817640, 'Dragonic Pendulum', '龙叁阵 灵摆', 'ドラゴニックP', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：场上的「龙剑士」怪兽的攻击力·守备力上升300。 ②：自己场上的龙族「龙剑士」怪兽把效果发动的场合，以场上1张卡为对象才能发动。那张卡破坏。 ③：场上的这张卡被破坏的场合才能发动。从卡组选1只「龙剑士」怪兽或者「龙魔王」怪兽加入手卡或特殊召唤。'),
(72549351, 'Dragonic Tactics', '龙棋战术', 'ドラゴニック・タクティクス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的2只龙族怪兽解放发动。从自己卡组把1只8星的龙族怪兽特殊召唤。'),
(3837261, 'Dragonic Warrior', '缔结契约的龙之战士', '契約を結びし竜の戦士', 'Effect Monster', 'Dragon', 'FIRE', 4, 1500, 1000, '这个卡名的效果1回合只能使用1次。 ①：丢弃1张手卡才能发动。除「缔结契约的龙之战士」外的1只4星以下的龙族怪兽从手卡·卡组特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(75083197, 'Dragonlark Pairen', '告天子龙 百灵', '告天子竜パイレン', 'XYZ Monster', 'Wyrm', 'WIND', 6, 2700, 1300, '6星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：只要「告天子龙 百灵」以外的从墓地特殊召唤的怪兽在场上表侧表示存在，这张卡不会被战斗·效果破坏。 ②：自己·对方的准备阶段把这张卡1个超量素材取除，以自己墓地1只5星以下的怪兽为对象才能发动。那只怪兽特殊召唤。'),
(12163590, 'Dragonmaid Cehrmba', '龙女仆・希幽媞露', 'ドラゴンメイド・シュテルン', 'Effect Monster', 'Dragon', 'DARK', 9, 2800, 1800, '这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。「半龙女仆·星夜龙女」以外的自己的墓地·除外状态的1只「半龙女仆」怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的龙族融合怪兽不会被对方的效果破坏。 ③：自己·对方的战斗阶段结束时才能发动。这张卡回到手卡，从手卡把1只4星以下的「半龙女仆」怪兽特殊召唤。'),
(40110009, 'Dragonmaid Changeover', '龙女仆的更衣', 'ドラゴンメイドのお召し替え', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己的手卡·场上的怪兽作为融合素材，把1只龙族融合怪兽融合召唤。 ②：这张卡在墓地存在的场合，以自己场上1只「半龙女仆」怪兽为对象才能发动。这张卡加入手卡，那只怪兽回到手卡。'),
(77515704, 'Dragonmaid Downtime', '龙女仆・休息', 'ドラゴンメイド・リラクゼーション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以以自己场上1只「半龙女仆」怪兽为对象，从以下效果选择1个发动。 ●作为对象的怪兽回到手卡，从卡组把「半龙女仆的休息」以外的1张「半龙女仆」卡加入手卡。 ●作为对象的怪兽回到手卡，对方场上1张魔法·陷阱卡回到手卡。'),
(76782778, 'Dragonmaid Ernus', '龙女仆・蔼儿地', 'ドラゴンメイド・エルデ', 'Effect Monster', 'Dragon', 'EARTH', 7, 2600, 1600, '这个卡名的①③的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡从手卡丢弃才能发动。从手卡把1只4星以下的「半龙女仆」怪兽特殊召唤。 ②：只要自己场上有融合怪兽存在，这张卡不会被效果破坏。 ③：自己·对方的战斗阶段结束时才能发动。这张卡回到手卡，从手卡把1只2星「半龙女仆」怪兽特殊召唤。'),
(78231355, 'Dragonmaid Hospitality', '龙女仆的无微不至', 'ドラゴンメイドのお心づくし', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·墓地把1只「半龙女仆」怪兽守备表示特殊召唤。那之后，可以把和这个效果特殊召唤的怪兽是等级不同并是属性相同的1只「半龙女仆」怪兽从卡组送去墓地。'),
(15848542, 'Dragonmaid Lorpar', '龙女仆・露风缇', 'ドラゴンメイド・ルフト', 'Effect Monster', 'Dragon', 'WIND', 8, 2700, 1700, '这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃，以场上1只表侧表示怪兽为对象才能发动。这个回合，双方不能把那只表侧表示怪兽的场上发动的效果发动。 ②：只要自己场上有融合怪兽存在，这张卡不会被效果破坏。 ③：自己·对方的战斗阶段结束时才能发动。这张卡回到手卡，从手卡把1只3星「半龙女仆」怪兽特殊召唤。'),
(49575521, 'Dragonmaid Nudyarl', '龙女仆・芙流丝', 'ドラゴンメイド・フルス', 'Effect Monster', 'Dragon', 'WATER', 7, 2600, 1600, '这个卡名的①③的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃，以自己或对方的墓地1只怪兽为对象才能发动。那只怪兽回到卡组。 ②：只要自己场上有融合怪兽存在，这张卡不会被效果破坏。 ③：自己·对方的战斗阶段结束时才能发动。这张卡回到手卡，从手卡把1只2星「半龙女仆」怪兽特殊召唤。'),
(15754711, 'Dragonmaid Send-Off', '龙女仆的送行', 'ドラゴンメイドのお見送り', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「半龙女仆」怪兽为对象才能发动。和那只怪兽卡名不同的1只「半龙女仆」怪兽从手卡守备表示特殊召唤，作为对象的怪兽回到持有者手卡。这个效果特殊召唤的怪兽直到下个回合的结束时不会被战斗·效果破坏。'),
(24799107, 'Dragonmaid Sheou', '龙女仆・秀特亮尔', 'ドラゴンメイド・シュトラール', 'Fusion Monster', 'Dragon', 'LIGHT', 10, 3500, 2000, '「半龙女仆」怪兽＋5星以上的龙族怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的准备阶段才能发动。从自己的手卡·墓地把1只9星以下的「半龙女仆」怪兽特殊召唤。 ②：对方把魔法·陷阱·怪兽的效果发动时才能发动。以下效果全部适用。 ●那个发动无效并破坏。 ●这张卡回到额外卡组，从额外卡组把1只「半龙女仆·龙女管家」特殊召唤。'),
(57416183, 'Dragonmaid Tidying', '龙女仆的收拾整理', 'ドラゴンメイドのお片付け', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只龙族怪兽和对方的场上·墓地1张卡为对象才能发动。那些卡回到手卡。 ②：把墓地的这张卡除外才能发动。从自己的手卡·墓地把1只「半龙女仆」怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到手卡。'),
(42055234, 'Dragonmaid Tinkhec', '龙女仆・弗燃梅', 'ドラゴンメイド・フランメ', 'Effect Monster', 'Dragon', 'FIRE', 8, 2700, 1700, '这个卡名的①③的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡从手卡丢弃，以自己场上1只「半龙女仆」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升2000。 ②：只要自己场上有融合怪兽存在，这张卡不会被效果破坏。 ③：自己·对方的战斗阶段结束时才能发动。这张卡回到手卡，从手卡把1只3星「半龙女仆」怪兽特殊召唤。'),
(14625090, 'Dragonmaid Welcome', '龙女仆的迎候', 'ドラゴンメイドのお出迎え', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的怪兽的攻击力·守备力上升自己场上的「半龙女仆」怪兽数量×100。 ②：自己场上有「半龙女仆」怪兽2只以上存在的场合，以「半龙女仆的迎接」以外的自己墓地1张「半龙女仆」卡为对象才能发动。那张卡加入手卡。 ③：这张卡被送去墓地的场合发动。这个回合中，对方不能把自己场上的「半龙女仆」怪兽作为效果的对象。'),
(28053763, 'Dragonoid Generator', '机龙生成器', 'ドラゴノイド・ジェネレーター', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '支付1000基本分才能把这张卡发动。这个卡名的①的效果1回合可以使用最多2次。 ①：自己主要阶段才能发动。把1只「机龙衍生物」（机械族·地·1星·攻/守300）在自己场上攻击表示特殊召唤。这个效果的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。这个回合的结束阶段，对方必须把1只「机龙衍生物」在自身场上攻击表示特殊召唤。'),
(28053764, 'Dragonoid Token', '机龙生成器', 'ドラゴノイド・ジェネレーター', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(92870717, 'Dragonox, the Empowered Warrior', '魔装战士 龙夜', '魔装戦士 ドラゴノックス', 'Pendulum Effect Monster', 'Warrior', 'DARK', 4, 1500, 1500, '①：1回合1次，丢弃1张手卡，以自己墓地的攻击力2000以下的1只战士族或者魔法师族怪兽为对象才能发动。那只怪兽里侧守备表示特殊召唤。'),
(51531505, 'Dragonpit Magician', '龙穴的魔术师', '竜穴の魔術師', 'Pendulum Normal Monster', 'Spellcaster', 'WATER', 7, 900, 2700, '年纪轻轻就领会唤醒龙魂的神通力的天才魔术师。由于他沉默寡言加上清心寡欲这种对魔术的态度而不擅长与人交际，但总被徒弟「龙脉之魔术师」折腾到抓狂。'),
(15146890, 'Dragonpulse Magician', '龙脉的魔术师', '竜脈の魔術師', 'Pendulum Normal Monster', 'Spellcaster', 'EARTH', 4, 1800, 900, '优点只有精力充沛的新手少年魔术师。其实有着无意识间觉察到大地长眠的龙魂这种能力，虽然还是半吊子但其资质之高就连师父「龙穴之魔术师」也自认不如。'),
(9069157, 'Dragonroid', '龙机人', 'ドラゴンロイド', 'Effect Monster', 'Machine', 'WIND', 8, 2900, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：可以把这张卡从手卡丢弃，从以下效果选择1个发动。 ●从卡组把1只风属性以外的「机人」怪兽加入手卡。 ●这个回合，包含把融合怪兽融合召唤效果的效果由自己发动的场合，那个发动不会被无效化，在那次融合召唤成功时对方不能把魔法·陷阱·怪兽的效果发动。 ②：1回合1次，这张卡在墓地存在的场合才能发动。墓地的这张卡直到回合结束时变成龙族。'),
(73779005, 'Dragoons of Draconia', '多拉科尼亚的兽龙骑兵', 'ドラコニアの獣竜騎兵', 'Pendulum Normal Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 200, '龙人族国家德拉科尼亚帝国所拥有的龙骑士团陆兵部队。使用鸟铳与铁枪组合攻击而无懈可击，令雷普提尔皇国等周边国家有所畏惧。'),
(34898052, 'Dragoroar', '牙龙咆哮', '牙竜咆哮', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把自己墓地的地·水·炎·风属性怪兽各1只除外才能发动。选场上1张卡回到持有者卡组。'),
(36870345, 'Dragunity Aklys', '龙骑兵团－小投枪', 'ドラグニティ－アキュリス', 'Tuner Monster', 'Dragon', 'WIND', 2, 1000, 800, '①：这张卡召唤成功时才能发动。从手卡把1只「龙骑兵团」怪兽特殊召唤，那之后，自己场上的表侧表示的这张卡当作装备卡使用给那只特殊召唤的怪兽装备。 ②：给怪兽装备的这张卡被送去墓地的场合，以场上1张卡为对象发动。那张卡破坏。'),
(88361177, 'Dragunity Angusticlavii', '龙骑兵团-窄带军事官', 'ドラグニティ－アングス', 'Effect Monster', 'Winged Beast', 'WIND', 5, 2100, 1000, '这张卡有名字带有「龙骑兵团」的龙族怪兽装备的场合，这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(53184342, 'Dragunity Arma Gram', '龙骑兵团武器－神怒剑', 'ドラグニティアームズ－グラム', 'Effect Monster', 'Dragon', 'WIND', 10, 2900, 2200, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，从自己墓地把2只其他的龙族·鸟兽族怪兽除外才能发动。这张卡特殊召唤。 ②：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的效果无效化，那个攻击力下降自己场上的装备卡数量×1000。 ③：对方怪兽被战斗破坏送去墓地时才能发动。那怪兽当作装备魔法卡使用给这张卡装备。'),
(63487632, 'Dragunity Arma Leyvaten', '龙骑兵团武器－灾魔剑', 'ドラグニティアームズ－レヴァテイン', 'Effect Monster', 'Dragon', 'WIND', 8, 2600, 1200, '①：这张卡可以把有「龙骑兵团」卡装备的自己场上1只怪兽除外，从手卡·墓地特殊召唤。 ②：这张卡召唤·特殊召唤成功时，以「龙骑兵团武器-灾魔剑」以外的自己墓地1只龙族怪兽为对象才能发动。那只龙族怪兽当作装备卡使用给这张卡装备。 ③：这张卡被对方的效果送去墓地时，以给这张卡装备的自己·对方的墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(876330, 'Dragunity Arma Mystletainn', '龙骑兵团武器－银槲剑', 'ドラグニティアームズ－ミスティル', 'Effect Monster', 'Dragon', 'WIND', 6, 2100, 1500, '①：这张卡可以把自己场上1只表侧表示的「龙骑兵团」怪兽送去墓地，从手卡特殊召唤。 ②：这张卡从手卡召唤·特殊召唤时，以自己墓地1只龙族「龙骑兵团」怪兽为对象才能发动。那只龙族怪兽当作装备魔法卡使用给这张卡装备。'),
(54455664, 'Dragunity Brandistock', '龙骑兵团-叉龙', 'ドラグニティ－ブランディストック', 'Tuner Monster', 'Dragon', 'WIND', 1, 600, 400, '①：把这张卡当作装备卡使用来装备的怪兽在同1次的战斗阶段中可以作2次攻击。'),
(99594764, 'Dragunity Corsesca', '龙骑兵团-翼枪龙', 'ドラグニティ－コルセスカ', 'Tuner Monster', 'Dragon', 'WIND', 1, 800, 700, '①：把这张卡当作装备卡使用来装备的怪兽战斗破坏对方怪兽时才能发动。种族·属性和装备怪兽相同的1只4星以下的怪兽从卡组加入手卡。'),
(29253591, 'Dragunity Couse', '龙骑兵团－长柄大刀', 'ドラグニティ－クーゼ', 'Tuner Monster', 'Dragon', 'WIND', 2, 1000, 200, '把这张卡作为同调素材的场合，不是「龙骑兵团」怪兽的同调召唤不能使用。 ①：把场上的这张卡作为同调素材的场合，可以把这张卡的等级当作4星使用。 ②：这张卡装备中的场合才能发动。这张卡特殊召唤。'),
(13361027, 'Dragunity Darkspear', '龙骑兵团－黑矛', 'ドラグニティ－ブラックスピア', 'Tuner Monster', 'Dragon', 'WIND', 3, 1000, 1000, '①：1回合1次，把自己场上1只龙族「龙骑兵团」怪兽解放，以自己墓地1只4星以下的鸟兽族怪兽为对象才能发动。那只鸟兽族怪兽特殊召唤。'),
(60004971, 'Dragunity Divine Lance', '龙骑兵团神枪', 'ドラグニティの神槍', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「龙骑兵团」怪兽才能装备。这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽攻击力上升自身的等级×100，不受陷阱卡的效果影响。 ②：自己主要阶段才能发动。从卡组把1只龙族「龙骑兵团」调整当作装备魔法卡使用给这张卡的装备怪兽装备。'),
(7917970, 'Dragunity Divine Wind', '神风之龙骑兵团', '神風のドラグニティ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。自己墓地有「龙之溪谷」存在的场合，以下效果各能适用。不存在的场合，从以下效果选1个适用。 ●从自己墓地把1只龙族·鸟兽族怪兽加入手卡。 ●从手卡把1只「龙骑兵团」怪兽特殊召唤。那之后，可以从卡组把1只龙族「龙骑兵团」怪兽当作装备魔法卡使用给这个效果特殊召唤的怪兽装备。'),
(52962804, 'Dragunity Draft', '龙骑兵团・阵风', 'ドラグニティ・ドラフト', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡的发动时，可以以自己墓地1只4星以下的「龙骑兵团」怪兽为对象。那个场合，那只怪兽加入手卡。 ②：这张卡在魔法与陷阱区域存在，原本等级是5星以上的自己的「龙骑兵团」怪兽攻击的场合，那只怪兽直到伤害步骤结束时不受对方的效果影响。'),
(28183605, 'Dragunity Dux', '龙骑兵团－执政官', 'ドラグニティ－ドゥクス', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1500, 1000, '①：这张卡召唤成功时，以自己墓地1只龙族·3星以下的「龙骑兵团」怪兽为对象才能发动。那只龙族怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力上升自己场上的「龙骑兵团」卡数量×200。'),
(8039562, 'Dragunity Falchion', '龙骑兵团－弯刃大刀', 'ドラグニティ－ファルシオン', 'Tuner Monster', 'Dragon', 'WIND', 2, 1300, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡·墓地的这张卡除外，以自己场上1只「龙骑兵团」怪兽为对象才能发动。从自己的卡组·墓地把1只龙族「龙骑兵团」怪兽当作装备魔法卡使用给作为对象的怪兽装备。 ②：把给「龙骑兵团」怪兽装备的这张卡送去墓地，以对方场上1张表侧表示卡为对象才能发动。那张卡除外。'),
(25845518, 'Dragunity Glow', '龙骑兵团・炽辉', 'ドラグニティ・グロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的卡组·墓地把1只5星以上的「龙骑兵团」怪兽加入手卡。 ②：把墓地的这张卡除外，以给「龙骑兵团」怪兽装备的自己的魔法与陷阱区域1张怪兽卡为对象才能发动。那张卡守备表示特殊召唤。'),
(69975751, 'Dragunity Guisarme', '龙骑兵团－草铁枪', 'ドラグニティ－ギザーム', 'Tuner Monster', 'Dragon', 'WIND', 3, 600, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时，以自己墓地的风属性·4星以下的1只龙族或者鸟兽族的怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：这张卡当作装备卡使用而装备中的场合才能发动。装备的这张卡特殊召唤。'),
(80549379, 'Dragunity Javelin', '龙骑兵团-标枪龙', 'ドラグニティ－ジャベリン', 'Tuner Monster', 'Dragon', 'WIND', 2, 1200, 800, '这张卡在怪兽卡区域上被破坏的场合，可以不送去墓地当作装备魔法卡使用给自己场上表侧表示存在的1只名字带有「龙骑兵团」的鸟兽族怪兽装备。'),
(88234821, 'Dragunity Knight - Areadbhair', '龙骑兵团骑士－日神炎枪', 'ドラグニティナイト－アラドヴァル', 'Synchro Monster', 'Dragon', 'WIND', 10, 3300, 3200, '「龙骑兵团」调整＋调整以外的怪兽1只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：对方把怪兽的效果发动时，从自己墓地把1只「龙骑兵团」怪兽除外才能发动。那个发动无效并除外。 ②：这张卡战斗破坏对方怪兽的伤害计算后才能发动。那只对方怪兽除外。 ③：同调召唤的这张卡被对方破坏的场合才能发动。对方场上的魔法·陷阱卡全部破坏。'),
(34528176, 'Dragunity Knight - Areus', '龙骑兵团骑士－阿瑞斯', 'ドラグニティナイト－アーレウス', 'Synchro Monster', 'Dragon', 'WIND', 8, 2900, 2500, '调整＋调整以外的同调怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：以最多有自己的魔法与陷阱区域的表侧表示的怪兽卡数量的对方场上的表侧表示卡为对象才能发动（这张卡有装备卡装备的场合，这个效果在对方回合也能发动）。那些卡的效果直到回合结束时无效。 ②：这张卡装备中的场合才能发动。这张卡特殊召唤。那之后，可以从自己墓地把1只「龙骑兵团」调整特殊召唤。'),
(48891960, 'Dragunity Knight - Ascalon', '龙骑兵团骑士－屠龙圣枪', 'ドラグニティナイト－アスカロン', 'Synchro Monster', 'Dragon', 'WIND', 10, 3300, 3200, '「龙骑兵团」调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：从自己墓地把1只「龙骑兵团」怪兽除外，以对方场上1只怪兽为对象才能发动。那只怪兽除外。 ②：同调召唤的这张卡被对方破坏的场合才能发动。从额外卡组把1只攻击力3000以下的「龙骑兵团」同调怪兽当作同调召唤作特殊召唤。'),
(25682811, 'Dragunity Knight - Barcha', '龙骑兵团骑士－轻木掷枪', 'ドラグニティナイト－バルーチャ', 'Synchro Monster', 'Dragon', 'WIND', 8, 2000, 1200, '龙族调整＋调整以外的鸟兽族怪兽1只以上 ①：这张卡同调召唤时，以自己墓地的龙族「龙骑兵团」怪兽任意数量为对象才能发动。那些龙族怪兽当作装备魔法卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡装备的「龙骑兵团」卡数量×300。'),
(900787, 'Dragunity Knight - Gae Bulg', '龙骑兵团骑士－凡界死枪', 'ドラグニティナイト－ゲイボルグ', 'Synchro Monster', 'Dragon', 'WIND', 6, 2000, 1100, '龙族调整＋调整以外的鸟兽族怪兽1只以上 ①：这张卡进行战斗的从伤害步骤开始时到伤害计算前1次，从自己墓地把1只鸟兽族怪兽除外才能发动。这张卡的攻击力直到回合结束时上升除外的那只怪兽的原本攻击力数值。'),
(34116027, 'Dragunity Knight - Gae Dearg', '龙骑兵团骑士－破魔赤枪', 'ドラグニティナイト－ガジャルグ', 'Synchro Monster', 'Dragon', 'WIND', 6, 2400, 800, '龙族调整＋调整以外的鸟兽族怪兽1只以上 ①：1回合1次，自己主要阶段才能发动。从卡组把1只4星以下的龙族·鸟兽族怪兽加入手卡。那之后，从手卡选1只龙族·鸟兽族怪兽丢弃。'),
(36556781, 'Dragunity Knight - Gormfaobhar', '龙骑兵团骑士－碧刃之枪', 'ドラグニティナイト－ゴルムファバル', 'Synchro Monster', 'Dragon', 'WIND', 7, 2600, 2300, '「龙骑兵团」调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤成功时，以自己墓地1只「龙骑兵团」调整为对象才能发动。那只怪兽当作装备卡使用给这张卡装备。 ②：把给这张卡装备的自己场上1张装备卡送去墓地，以对方墓地最多2张卡为对象才能发动。那些卡除外。这个效果在对方回合也能发动。'),
(12496261, 'Dragunity Knight - Luin', '龙骑兵团骑士－嗜毒魔枪', 'ドラグニティナイト－ハールーン', 'Synchro Tuner Monster', 'Dragon', 'WIND', 6, 1200, 1900, '「龙骑兵团」调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以自己墓地1只「龙骑兵团」怪兽为对象才能发动。那只怪兽当作装备魔法卡使用给这张卡装备。 ②：这张卡被送去墓地的场合，以自己场上1只「龙骑兵团」怪兽为对象才能发动。这张卡当作攻击力·守备力上升1000的装备魔法卡使用给作为对象的自己怪兽装备。'),
(11969228, 'Dragunity Knight - Romulus', '龙骑兵团骑士－罗慕路斯', 'ドラグニティナイト－ロムルス', 'Link Monster', 'Dragon', 'WIND', NULL, 1200, NULL, '衍生物以外的龙族·鸟兽族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1张「龙骑兵团」魔法·陷阱卡或「龙之溪谷」加入手卡。 ②：龙族怪兽从额外卡组往这张卡所连接区特殊召唤的场合才能发动。从手卡把1只龙族·鸟兽族怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在这个回合效果无效化，不能作为连接素材。'),
(80159717, 'Dragunity Knight - Trident', '龙骑兵团骑士－三叉之枪', 'ドラグニティナイト－トライデント', 'Synchro Monster', 'Dragon', 'WIND', 7, 2400, 1700, '龙族调整＋调整以外的鸟兽族怪兽1只以上 ①：1回合1次，把自己场上最多3张卡送去墓地才能发动。把对方的额外卡组确认，选为这个效果发动而送去墓地的数量的卡送去墓地。'),
(21249921, 'Dragunity Knight - Vajrayana', '龙骑兵团骑士－圣雷牙枪', 'ドラグニティナイト－ヴァジュランダ', 'Synchro Monster', 'Dragon', 'WIND', 6, 1900, 1200, '龙族调整＋调整以外的鸟兽族怪兽1只以上 ①：这张卡同调召唤时，以自己墓地1只3星以下的龙族「龙骑兵团」怪兽为对象才能发动。那只龙族怪兽当作装备魔法卡使用给这张卡装备。 ②：1回合1次，把这张卡装备的自己场上1张装备卡送去墓地才能发动。这张卡的攻击力直到回合结束时变成2倍。'),
(89172051, 'Dragunity Legatus', '龙骑兵团－司令官', 'ドラグニティ－レガトゥス', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1800, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己场上有「龙骑兵团」怪兽或「龙之溪谷」存在的场合才能发动。这张卡特殊召唤。 ②：自己的魔法与陷阱区域有「龙骑兵团」怪兽卡存在的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(28927782, 'Dragunity Legion', '龙骑兵团疾驰', 'ドラグニティ・ドライブ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。这个回合，自己不是「龙骑兵团」怪兽不能特殊召唤。 ●以自己的魔法与陷阱区域1张「龙骑兵团」怪兽卡为对象才能发动。那张卡守备表示特殊召唤。 ●以自己场上1只「龙骑兵团」怪兽为对象才能发动。从自己墓地选1只「龙骑兵团」怪兽当作装备卡使用给作为对象的自己怪兽装备。'),
(54578613, 'Dragunity Legionnaire', '龙骑兵团－军团长', 'ドラグニティ－レギオン', 'Effect Monster', 'Winged Beast', 'WIND', 3, 1200, 800, '①：这张卡召唤成功时，以自己墓地1只龙族·3星以下的「龙骑兵团」怪兽为对象才能发动。那只龙族怪兽当作装备卡使用给这张卡装备。 ②：把自己的魔法与陷阱区域1张表侧表示的「龙骑兵团」卡送去墓地，以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽破坏。'),
(70522875, 'Dragunity Lord - Georgius', '龙骑兵团领主－格奥鲁吉亚斯', 'ドラグニティロード－ゲオルギアス', 'Link Monster', 'Dragon', 'WIND', NULL, 2400, NULL, '包含调整的怪兽2只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡连接召唤的场合或者对方把怪兽特殊召唤的场合才能发动。从自己的额外卡组·墓地把1只5星以上的「龙骑兵团」怪兽特殊召唤。 ②：只要这张卡有「龙骑兵团」卡装备，对方不能把墓地的怪兽的效果发动。 ③：对方把魔法·陷阱卡的效果发动时，把自己场上1张装备卡送去墓地才能发动。那个效果无效。'),
(81661951, 'Dragunity Militum', '龙骑兵团-士兵', 'ドラグニティ－ミリトゥム', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1700, 1200, '选择自己的魔法与陷阱卡区域存在的1张名字带有「龙骑兵团」的卡发动。选择的卡在自己场上特殊召唤。这个效果1回合只能使用1次。'),
(51849216, 'Dragunity Oubliette', '龙骑兵团・虚炼', 'ドラグニティ・ヴォイド', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「龙骑兵团」同调怪兽存在，对方把魔法·陷阱卡发动时才能发动。那个发动无效并除外。自己场上有10星「龙骑兵团」怪兽存在的场合，可以再让自己场上1只「龙骑兵团」怪兽的攻击力上升表侧除外中的卡数量×100。'),
(25988873, 'Dragunity Partisan', '龙骑兵团-阔头枪龙', 'ドラグニティ－パルチザン', 'Tuner Monster', 'Dragon', 'WIND', 2, 1200, 800, '这张卡召唤成功时，可以从手卡把1只名字带有「龙骑兵团」的鸟兽族怪兽特殊召唤，把这张卡当作装备卡使用来装备。这张卡被卡的效果当作装备卡使用装备中的场合，装备怪兽当作调整使用。'),
(59755122, 'Dragunity Phalanx', '龙骑兵团－方阵', 'ドラグニティ－ファランクス', 'Tuner Monster', 'Dragon', 'WIND', 2, 500, 1100, '①：这张卡装备中的场合，1回合1次，自己主要阶段才能发动。这张卡特殊召唤。'),
(52977572, 'Dragunity Pilum', '龙骑兵团-重标枪龙', 'ドラグニティ－ピルム', 'Tuner Monster', 'Dragon', 'WIND', 3, 1400, 1000, '这张卡召唤成功时，可以从手卡把1只名字带有「龙骑兵团」的鸟兽族怪兽特殊召唤，把这张卡当作装备卡使用来装备。这张卡被卡的效果当作装备卡使用装备中的场合，装备怪兽可以直接攻击对方玩家。这个时候，装备怪兽给与对方基本分的战斗伤害变成一半数值。'),
(18060565, 'Dragunity Primus Pilus', '龙骑兵团－首席百夫长', 'ドラグニティ－プリムス・ピルス', 'Effect Monster', 'Winged Beast', 'WIND', 5, 2200, 1600, '①：这张卡召唤·特殊召唤成功时，以自己场上1只鸟兽族「龙骑兵团」怪兽为对象才能发动。从卡组选1只龙族·3星以下的「龙骑兵团」怪兽当作装备卡使用给作为对象的怪兽装备。'),
(71645463, 'Dragunity Quirinus', '龙骑兵团－奎里纳斯', 'ドラグニティ－クイリヌス', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1200, 1200, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「龙骑兵团」魔法·陷阱卡加入手卡。 ②：只要这张卡有装备卡装备，自己的「龙骑兵团」怪兽不会被战斗破坏。 ③：以自己场上1张其他的「龙骑兵团」怪兽卡为对象才能发动。那张卡回到手卡·额外卡组。那之后，可以从手卡把1只「龙骑兵团」怪兽特殊召唤。'),
(26577155, 'Dragunity Remus', '龙骑兵团－雷穆斯', 'ドラグニティ－レムス', 'Tuner Monster', 'Dragon', 'WIND', 2, 800, 800, '这个卡名的①②的效果1回合各能使用1次，把这张卡作为同调素材的场合，不是「龙骑兵团」怪兽的同调召唤不能使用。 ①：把这张卡从手卡丢弃才能发动。从卡组把1张「龙之溪谷」加入手卡。 ②：自己场上有「龙骑兵团」怪兽存在的场合才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个回合，自己不是龙族怪兽不能从额外卡组特殊召唤。'),
(92868896, 'Dragunity Senatus', '龙骑兵团－元老院', 'ドラグニティ－セナート', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1800, 600, '这个卡名的①的效果1回合只能使用1次。 ①：从手卡丢弃1张「龙骑兵团」卡才能发动。从卡组选1只「龙骑兵团」调整当作装备卡使用给这张卡装备。这个效果的发动后，直到回合结束时自己不是龙族怪兽不能从额外卡组特殊召唤。 ②：自己场上的「龙骑兵团」卡被战斗·效果破坏的场合，可以作为代替把给这张卡装备的1张「龙骑兵团」卡破坏。'),
(81962318, 'Dragunity Tribus', '龙骑兵团－保民官', 'ドラグニティ－トリブル', 'Effect Monster', 'Winged Beast', 'WIND', 1, 500, 300, '这张卡召唤·特殊召唤成功时，可以从自己卡组把1只3星以下的龙族怪兽送去墓地。'),
(89450409, 'Dragunity Whirlwind', '疾风之龙骑兵团', '疾風のドラグニティ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：只有对方场上才有怪兽存在的场合才能发动。从卡组把「龙骑兵团」调整和鸟兽族「龙骑兵团」怪兽各1只效果无效特殊召唤。从额外卡组特殊召唤的怪兽在对方场上存在的场合，可以再只用自己场上的「龙骑兵团」怪兽为素材把1只龙族同调怪兽同调召唤。这张卡的发动后，直到回合结束时自己不是龙族怪兽不能从额外卡组特殊召唤。'),
(43250041, 'Draining Shield', '吸收盾', 'ドレインシールド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时，以1只攻击怪兽为对象才能发动。那只攻击怪兽的攻击无效，自己回复那只怪兽的攻击力数值的基本分。'),
(81096431, 'Drake Shark', '龙兽鲨', 'ドレイク・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1400, 1050, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。 ②：以怪兽3只以上为素材的水属性超量怪兽超量召唤的场合，这张卡可以作为2只数量的超量素材。 ③：持有这张卡作为素材中的「鲨龙兽」超量怪兽得到以下效果。 ●1回合1次，把这张卡2个超量素材取除，以场上1张魔法·陷阱卡为对象才能发动。那张卡作为这张卡的超量素材。'),
(80193355, 'Dramatic Rescue', '救出剧', '救出劇', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '以场上存在的名称中含有「亚马逊」字样的怪兽为对象的卡发动时这张卡才能发动。将成为对象的怪兽卡弹回持有者手卡，从自己手卡中特殊召唤另1只怪兽上场。'),
(26700718, 'Dramatic Snake-Eye Chase', '蛇眼追逐剧', 'スネークアイ追走劇', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·卡组·墓地把1只「迪亚贝尔斯塔尔」怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。 ②：自己·对方的结束阶段，把墓地的这张卡除外，以自己场上1张当作永续魔法卡使用的怪兽卡为对象才能发动。那张卡特殊召唤。'),
(99456344, 'Dramaturge of Despia', '惨绝戏之大导剧神', 'デスピアの大導劇神', 'Effect Monster', 'Fairy', 'DARK', 8, 3000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：融合·同调·超量·连接怪兽特殊召唤的场合，以场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。 ②：手卡·场上的这张卡成为融合召唤的素材，被送去墓地的场合或者被除外的场合才能发动。这张卡特殊召唤。'),
(79966218, 'Draselea the Blood Tree Dragon Princess', NULL, NULL, 'Tuner Monster', 'Plant', 'DARK', 1, NULL, NULL, NULL),
(70366448, 'Drastic Draw', '猛攻抽牌', 'ドラスティック・ドロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是电子界族怪兽不能召唤·特殊召唤。 ①：把2只以上的自己场上的怪兽全部除外才能发动。自己抽3张。'),
(4440873, 'Drastic Drop Off', '强烈的打落', '強烈なはたき落とし', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：对方从卡组把卡加入手卡时才能发动。对方把加入手卡的那1张卡丢弃。'),
(26557451, 'Draw Discharge', '抽卡放电', 'ドロー・ディスチャージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方的效果让对方抽卡时才能发动。对方抽到的那些卡全部确认。那之中有怪兽卡的场合，给与对方那个攻击力合计数值的伤害，确认的卡全部除外。'),
(41367003, 'Draw Muscle', '抽卡肌肉', 'ドロー・マッスル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「抽卡肌肉」在1回合只能发动1张。 ①：以自己场上1只守备力1000以下的表侧守备表示怪兽为对象才能发动。自己从卡组抽1张。那只怪兽在这个回合不会被战斗破坏。'),
(856784, 'Draw of Fate', '命定的抽牌', '運命のドロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己基本分比对方少，场上的攻击力最高的怪兽在对方场上存在的场合才能发动。从卡组选3张卡名不同的卡给对方观看，那3张洗切回到卡组上面。那之后，自己从卡组抽1张。这张卡的发动后，直到回合结束时自己不能把魔法·陷阱卡盖放，只能有1次把魔法·陷阱·怪兽的效果发动。'),
(83838727, 'Drawbread', '抽牌面包', 'ドローパン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己墓地有怪兽存在的场合，支付200基本分才能发动。自己抽1张，给双方确认。那是怪兽的场合，再让那个属性的以下效果适用。 ●不在自己墓地存在的属性：自己抽1张。 ●自己墓地存在的属性：选自己1张手卡丢弃。'),
(51925772, 'Dread Dragon', '可怖龙', 'ドレッド・ドラゴン', 'Tuner Monster', 'Dragon', 'FIRE', 2, 1100, 400, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只3星以下的龙族怪兽加入手卡。'),
(66973070, 'Dreadscythe Harvester', '死镰杀手', 'デスサイズ・キラー', 'Effect Monster', 'Insect', 'WIND', 8, 2300, 1600, '①：把这张卡以外的自己场上1只昆虫族怪兽解放才能发动。这张卡的攻击力直到回合结束时上升500。'),
(5068132, 'Dream Cicada', '梦蝉 睡鸣眠', '夢蝉スイミンミン', 'Effect Monster', 'Insect', 'WIND', 3, 300, 1300, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有攻击表示的昆虫族怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合，以场上1只怪兽为对象才能发动。那只怪兽的表示形式变更。'),
(13215230, 'Dream Clown', '梦幻小丑', 'ドリーム・ピエロ', 'Effect Monster', 'Warrior', 'EARTH', 3, 1200, 900, '这张卡的表示形式从攻击表示变成守备表示时，破坏对方场上的1只怪兽。'),
(37444964, 'Dream Mirror Fantasy', '梦魔镜之梦物语', '夢魔鏡の夢物語', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「梦魔镜」怪兽存在的场合，以除外的自己的「圣光之梦魔镜」「黯黑之梦魔镜」各1张为对象才能发动。那些卡回到卡组，选场上1张卡除外。 ②：自己场上的「梦魔镜」卡被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(25964547, 'Dream Mirror Hypnagogia', '梦现之梦魔镜', '夢現の夢魔鏡', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：「圣光之梦魔镜」「黯黑之梦魔镜」各1张从手卡·卡组选出，那之内的1张在自己的场地区域，另1张在对方的场地区域各自表侧表示放置。'),
(98570539, 'Dream Mirror of Chaos', '混沌之梦魔镜', '混沌の夢魔鏡', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：「梦魔镜」融合怪兽卡决定的融合素材怪兽从自己场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。场地区域有「圣光之梦魔镜」存在的场合，手卡的怪兽也能作为融合素材。场地区域有「黯黑之梦魔镜」存在的场合，也能把自己墓地的怪兽除外作为融合素材。'),
(74665651, 'Dream Mirror of Joy', '圣光之梦魔镜', '聖光の夢魔鏡', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有光属性「梦魔镜」怪兽存在，自己场上的「梦魔镜」怪兽之内除等级最高的怪兽以外的「梦魔镜」怪兽不会成为攻击对象，也不会成为对方的效果的对象。 ②：自己·对方的结束阶段，把自己的场地区域的这张卡除外才能发动。从手卡·卡组把1张「黯黑之梦魔镜」发动。'),
(1050355, 'Dream Mirror of Terror', '暗黑之梦魔镜', '闇黒の夢魔鏡', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有暗属性「梦魔镜」怪兽存在，每次对方对怪兽的特殊召唤成功，给与对方300伤害。 ②：自己·对方的结束阶段，把自己的场地区域的这张卡除外才能发动。从手卡·卡组把1张「圣光之梦魔镜」发动。'),
(61459246, 'Dream Mirror Oneiromancy', '梦魔镜之占梦', '夢魔鏡の夢占い', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以把以下效果发动。 ●场地区域有「圣光之梦魔镜」存在，对方把魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ●场地区域有「黯黑之梦魔镜」存在，对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。'),
(62171834, 'Dream Mirror Phantasms', '梦幻之梦魔镜', '夢幻の夢魔鏡', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「梦魔镜」怪兽加入手卡。 ②：只要场地区域有「圣光之梦魔镜」存在，自己场上的全部怪兽的攻击力·守备力上升500。 ③：只要场地区域有「黯黑之梦魔镜」存在，对方场上的全部怪兽的攻击力·守备力下降500。'),
(81038234, 'Dream Mirror Recap', '梦魔镜之述梦', '夢魔鏡の夢語らい', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的「梦魔镜」怪兽为让自身的效果发动而被解放的场合，不去墓地回到持有者卡组。 ②：自己·对方的主要阶段，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。从自己墓地的卡以及除外的自己的卡之中选1张「圣光之梦魔镜」或者「黯黑之梦魔镜」在自己的场地区域表侧表示放置。那之后，可以把有放置的卡的卡名记述的1只怪兽从手卡特殊召唤。'),
(6180710, 'Dream Shark', '梦鲨', 'ドリーム・シャーク', 'Effect Monster', 'Fish', 'WATER', 5, NULL, 2600, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上的怪兽不存在的场合或者只有水属性怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡1回合只有1次不会被战斗破坏。 ③：这张卡在墓地存在，给与自己伤害的效果发动时才能发动。这张卡特殊召唤，那个效果让自己受到的伤害变成0。这个效果特殊召唤的这张卡守备力下降1000，从场上离开的场合除外。'),
(18458255, 'Dream Tower of Princess Nemleria', '妮梦雷莉娅的寝姬楼', 'ネムレリアの寝姫楼', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：从额外卡组把2张里侧表示的卡里侧表示除外才能发动。从卡组把2只卡名不同的兽族·10星怪兽加入手卡。这个效果发动的回合，自己不是灵摆怪兽不能从额外卡组特殊召唤。 ②：自己的额外卡组有表侧表示的「梦见之妮穆蕾莉娅」存在，自己场上的「妮穆蕾莉娅」怪兽被战斗或者对方的效果破坏的场合，可以作为代替把自己的额外卡组1张里侧表示的卡里侧表示除外。'),
(70155677, 'Dreaming Nemleria', '眠梦中的妮梦雷莉娅', '夢見るネムレリア', 'Pendulum Effect Monster', 'Fairy', 'LIGHT', 1, NULL, 1500, '这张卡不能通常召唤。这张卡在额外卡组表侧表示存在，自己的额外卡组只有「梦见之妮穆蕾莉娅」存在的场合才能特殊召唤。自己对「梦见之妮穆蕾莉娅」1回合只能有1次特殊召唤。 ①：这张卡特殊召唤成功的场合才能发动。里侧表示除外的自己的卡每有3张，选对方的场上·墓地最多1张卡里侧表示除外。那之后，选这个效果除外的卡数量的里侧表示除外的自己的卡回到卡组。'),
(16893370, 'Dreaming Reality of Nemleria, Realized', '梦现的寝姬－妮梦雷莉娅・蕾莉泽', '夢現の寝姫－ネムレリア・レアリゼ', 'Effect Monster', 'Fairy', 'LIGHT', 10, 1500, 3000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，以自己场上1只怪兽为对象才能发动。那只怪兽回到卡组最下面，这张卡特殊召唤。 ②：这张卡特殊召唤的场合，可以从以下效果选择1个发动。 ●从卡组把1只「梦见之妮穆蕾莉娅」表侧加入额外卡组。 ●场上1只其他的表侧表示怪兽变成里侧守备表示。 ③：这张卡的攻击力上升自己的额外卡组的里侧的卡数量×100。'),
(26920296, 'Dreamland', '幻梦境', '幻夢境', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「幻梦境」在1回合只能发动1张。 ①：得到场上的怪兽种类的以下效果。 ●融合：1回合1次，自己的手卡·场上的怪兽被效果送去墓地的场合才能发动。自己从卡组抽1张。 ●同调：怪兽的召唤·特殊召唤成功时才能由自己把这个效果发动。那些怪兽的等级上升1星。 ●超量：自己结束阶段发动。场上的等级最高的怪兽破坏。'),
(8687195, 'Dreamsprite', '幻影妖精', '幻影の妖精', 'Effect Monster', 'Plant', 'LIGHT', 2, 300, 200, '这张卡受到从对方怪兽来的攻击的场合，让其他的自己场上1只怪兽承受攻击，进行伤害计算。'),
(94982447, 'Dreiath III, the True Dracocavalry General', '真龙骑将 德利亚Ⅲ世', '真竜騎将ドライアスⅢ世', 'Effect Monster', 'Wyrm', 'EARTH', 6, 2100, 2800, '这张卡表侧表示上级召唤的场合，可以作为怪兽的代替而把自己场上的永续魔法·永续陷阱卡解放。 ①：上级召唤的表侧表示的这张卡从场上离开的场合才能发动。从卡组把1只「真龙」怪兽守备表示特殊召唤。 ②：只要这张卡在怪兽区域存在，这张卡以外的场上的「真龙」怪兽不会成为对方的效果的对象，不会被对方的效果破坏。'),
(98248208, 'Driangle, Dragon of the Dark Deep', '暗黑海龙－龙三角', '暗黒海龍－ドライアグル', 'Effect Monster', 'Sea Serpent', 'WATER', 10, 2100, 3100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己的场上·墓地·除外状态的10星怪兽是3只以上的场合才能发动。这张卡特殊召唤。 ②：这张卡特殊召唤的场合，把自己卡组最上面的卡送去墓地才能发动。这张卡的攻击力上升500。那之后，送去墓地的卡是怪兽的场合，给与对方1000伤害。不是的场合，可以把自己卡组最上面的卡送去墓地。'),
(28265983, 'Dried Winds', '干渴之风', '渇きの風', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「干渴之风」的①②的效果1回合各能使用1次。 ①：自己基本分回复的场合，以对方场上1只表侧表示怪兽为对象把这个效果发动。那只怪兽破坏。 ②：自己场上有「芳香」怪兽存在，自己基本分比对方多3000以上的场合，支付那个相差数值的基本分才能把这个效果发动。攻击力合计最多到为这个效果发动而支付的基本分数值以下为止，选对方场上的表侧表示怪兽破坏。'),
(46221535, 'Drill Armed Dragon', '钻头武装龙', 'ドリル・アームド・ドラゴン', 'Effect Monster', 'Dragon', 'WIND', 3, 1100, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1只风属性怪兽送去墓地才能发动。这个回合中，自己场上的龙族·风属性怪兽的攻击力上升300。 ②：从自己墓地把风属性或7星以上的龙族怪兽任意数量除外才能发动。把持有和除外的怪兽数量相同等级的1只「钻头武装龙」以外的龙族怪兽从卡组加入手卡。'),
(24137081, 'Drill Barnacle', '钻头藤壶', 'ドリル・バーニカル', 'Effect Monster', 'Aqua', 'WATER', 3, 300, NULL, '这张卡可以直接攻击对方玩家。每次这张卡直接攻击给与对方基本分战斗伤害，这张卡的攻击力上升1000。'),
(88733579, 'Drill Bug', '穿孔虫', '穿孔虫', 'Effect Monster', 'Insect', 'EARTH', 2, 1100, 200, '这张卡给与对方战斗伤害的时候，从自己的卡组取出1张「寄生虫 帕拉赛德」，之后在卡组洗切后放在卡组最上面。'),
(39317553, 'Drill Driver Vespenato', '旋坏钻蜂 贝斯佩内特', '旋壊のヴェスペネイト', 'XYZ Monster', 'Machine', 'EARTH', 5, 2500, 2100, '5星怪兽×2 「旋坏之贯破黄蜂巢」1回合1次也能在自己场上的4阶超量怪兽上面重叠来超量召唤。这张卡在超量召唤的回合不能作为超量召唤的素材。这个卡名的②的效果1回合只能使用1次。 ①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：超量召唤的这张卡被对方破坏的场合，以自己墓地1只5星以下的怪兽为对象才能发动。那只怪兽特殊召唤。'),
(56286179, 'Drill Synchron', '钻头同步士', 'ドリル・シンクロン', 'Tuner Monster', 'Machine', 'EARTH', 3, 800, 300, '①：只要这张卡在怪兽区域存在，自己的战士族怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：1回合1次，这张卡的①的效果适用给与对方战斗伤害时才能发动。自己从卡组抽1张。'),
(3429238, 'Drill Warrior', '钻头战士', 'ドリル・ウォリアー', 'Synchro Monster', 'Warrior', 'EARTH', 6, 2400, 2000, '「钻头同调士」＋调整以外的怪兽1只以上 1回合1次，自己的主要阶段时才能发动。这张卡的攻击力变成一半，这个回合这张卡可以直接攻击对方玩家。此外，1回合1次，自己的主要阶段时才能发动。丢弃1张手卡并把这张卡从游戏中除外。下次的自己的准备阶段时，这个效果除外的这张卡在自己场上特殊召唤。那之后，选自己墓地1只怪兽加入手卡。');